      TS_LEX_ADVANCE_MAP_DENSE(33, ts_lex_advance_map_0);
      if (('1' <= lookahead && lookahead <= '9')) ADVANCE(170);
      if (('\t' <= lookahead && lookahead <= '\r') ||
          lookahead == ' ' ||
          lookahead == 0xa0 ||
          lookahead == 0x200b ||
          lookahead == 0x2060 ||
          lookahead == 0xfeff) SKIP(119);
      if (('C' <= lookahead && lookahead <= 'z') ||
          (0x80 <= lookahead && lookahead <= 0xffff)) ADVANCE(307);
      END_STATE();
    case 1:
